#pragma once
#include <string>
#include <vector>

#include "FlashcardCardActions.h"
#include "activities/Activity.h"
#include "util/ButtonNavigator.h"

// Settings > Marked and suspended: every marked or suspended card, grouped by
// deck, to clean decks up (e.g. ones generated by AI). A card row offers
// mark/unmark, suspend/reactivate, reset and delete; a deck row acts on all of
// its listed cards (delete the marked ones, reactivate the suspended ones,
// unmark all). Changes are written to the deck files at once.
class FlashcardFlaggedActivity final : public Activity {
  static constexpr size_t MAX_LISTED = 80;  // keeps the list's RAM small; more show up after a clean-up

  enum class View : uint8_t { List, Actions, Confirm };
  enum class Act : uint8_t { ToggleMark, ToggleSuspend, Reset, Delete, DeleteMarked, UnsuspendAll, UnmarkAll };
  struct Item {
    bool isDeck = false;
    std::string path;
    int card = -1;  // card row: index into cards
    uint16_t marked = 0;
    uint16_t suspended = 0;
  };

  ButtonNavigator buttonNavigator;
  std::vector<FlashcardCardActions::Flagged> cards;
  std::vector<Item> items;
  int selected = 0;
  View view = View::List;
  std::vector<Act> acts;
  int actSelected = 0;
  Act pendingConfirm = Act::Delete;

  void reload();
  void openActions();
  void run(Act act);
  void renderList(int top, int bottom);
  void renderActions(int top, int bottom);

 public:
  explicit FlashcardFlaggedActivity(GfxRenderer& renderer, MappedInputManager& mappedInput)
      : Activity("FlashcardFlagged", renderer, mappedInput) {}

  void onEnter() override;
  void loop() override;
  void render(RenderLock&&) override;
};
